    <?php foreach (($importLogs ?? []) as $historyLog): $historyStats = $historyLog['stats'] ?? []; if (empty($historyStats['updated_inspections'])) continue; ?><details class="mb-3"><summary><i class="fa-solid fa-clock-rotate-left me-1" aria-hidden="true"></i>Nachbearbeitung aus Import vom <?= htmlspecialchars((string) ($historyLog['created_at'] ?? ''), ENT_QUOTES) ?></summary><div class="table-responsive mt-2"><table class="table table-sm align-middle mb-0"><thead><tr><th>Prüfung</th><th>Gerät</th><th>Speicherplatz</th><th>Ergebnis</th></tr></thead><tbody><?php foreach ($historyStats['updated_inspections'] as $historyInspection): $historyStatus = InspectionEvaluationService::presentation((string) ($historyInspection['status'] ?? '')); $isSlot = !empty($historyInspection['number_is_storage_slot']); ?><tr><td><a href="<?= htmlspecialchars(url_for('admin/pruefungen/' . (int) ($historyInspection['id'] ?? 0)), ENT_QUOTES) ?>"><?= htmlspecialchars($isSlot ? 'Prüfung öffnen' : (string) ($historyInspection['number'] ?? 'Prüfung')) ?></a><?= $isSlot ? '<div class="small text-body-secondary">Prüfnummer im Import fehlt</div>' : '' ?></td><td><?= htmlspecialchars(trim((string) ($historyInspection['device_number'] ?? '') . ' · ' . (string) ($historyInspection['device_name'] ?? '')) ?: '—') ?></td><td><?= htmlspecialchars((string) ($historyInspection['storage_slot'] ?? '—')) ?></td><td><span class="badge text-bg-<?= htmlspecialchars($historyStatus['class'], ENT_QUOTES) ?>"><i class="fa-solid <?= htmlspecialchars($historyStatus['icon'], ENT_QUOTES) ?> me-1" aria-hidden="true"></i><?= htmlspecialchars($historyStatus['label']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></details><?php endforeach; ?>
