    <?php if (is_array($stats)): ?><div class="row g-2 mb-3"><?php foreach (['files' => 'Dateien', 'imported' => 'Prüfungen neu', 'updated' => 'Prüfungen aktualisiert', 'devices' => 'Geräte neu', 'reports' => 'Berichte', 'skipped' => 'Übersprungen'] as $key => $label): ?><div class="col-6 col-md-2"><div class="border rounded p-2 text-center"><div class="small text-body-secondary"><?= $label ?></div><strong><?= (int) ($stats[$key] ?? 0) ?></strong></div></div><?php endforeach; ?></div><details class="mb-3"><summary>Debug-Output anzeigen</summary><pre class="small mt-2"><?= htmlspecialchars((string) json_encode($stats, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)) ?></pre></details><?php endif; ?>
    <?php if (current_user_is_superadmin()): ?><details class="card border-danger mb-3" id="legacy-import-rebuild" data-action-nav="Quellen-Neuaufbau" data-action-icon="fa-triangle-exclamation"><summary class="card-header fw-semibold text-danger"><i class="fa-solid fa-arrows-rotate me-1" aria-hidden="true"></i>Importbestand aus kuratierten Quellen neu aufbauen</summary><div class="card-body"><p class="small text-body-secondary">Erstellt zuerst ein geprüftes Datenbank-Backup, entfernt ausschließlich JSON-/CSV-Importprüfungen und setzt Rechnungsdaten zurück. Anschließend läuft der normale, fortsetzbare Verzeichnisimport. Prüfweb-Prüfungen bleiben erhalten.</p><form method="post" class="row g-2"><input type="hidden" name="action" value="import_rebuild_preview"><div class="col-md-9"><label class="form-label" for="rebuild_directory">Kuratiertes Quellenverzeichnis</label><input class="form-control" id="rebuild_directory" name="rebuild_directory" required value="<?= htmlspecialchars((string) ($_POST['rebuild_directory'] ?? ''), ENT_QUOTES) ?>" placeholder="Serverpfad mit JSON/JSONL und vollständigen CSV/ODS-Paaren"></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-outline-danger w-100"><i class="fa-solid fa-magnifying-glass me-1" aria-hidden="true"></i>Vorschau prüfen</button></div></form><?php if (is_array($rebuildPreview ?? null)): $rebuildAudit=$rebuildPreview['audit']; $rebuildReset=$rebuildPreview['reset']; ?><div class="alert alert-warning mt-3 mb-2"><strong>Vorschau:</strong> <?= (int) ($rebuildReset['imported_inspections'] ?? 0) ?> Importprüfungen und <?= (int) ($rebuildReset['billing_invoices_to_reset'] ?? 0) ?> Rechnungen werden zurückgesetzt. Quellen: <?= (int) ($rebuildAudit['json']['records'] ?? 0) ?> JSON, <?= (int) ($rebuildAudit['jsonl']['records'] ?? 0) ?> JSONL, <?= (int) ($rebuildAudit['csv_ods']['pairs'] ?? 0) ?> CSV/ODS-Paare.</div><?php if (($rebuildAudit['csv_ods']['unpaired_csv'] ?? []) !== []): ?><div class="alert alert-danger">Nicht startbar: <?= count($rebuildAudit['csv_ods']['unpaired_csv']) ?> CSV-Datei(en) ohne passende ODS.</div><?php else: ?><form method="post" class="row g-2 mt-1"><input type="hidden" name="action" value="import_rebuild_start"><input type="hidden" name="rebuild_directory" value="<?= htmlspecialchars((string) $rebuildPreview['directory'], ENT_QUOTES) ?>"><div class="col-md-8"><label class="form-label">Bestätigung</label><input class="form-control" name="rebuild_confirmation" required placeholder="IMPORT NEU AUFBAUEN"></div><div class="col-md-4 d-flex align-items-end"><button class="btn btn-danger w-100"><i class="fa-solid fa-database me-1" aria-hidden="true"></i>Backup, Reset &amp; Import starten</button></div></form><?php endif; ?><?php endif; ?></div></details><?php endif; ?>
