          <?php if (!empty($candidateRebuildRunning)): ?><div class="alert alert-primary mt-3 mb-0"><span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>Der Kandidatenlauf verarbeitet noch Quellen. Die offenen Fälle werden erst nach Abschluss geladen.</div><?php elseif (($candidateGroups ?? []) !== []): ?>
            <hr><div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-2"><p class="mb-0"><strong>Kandidatenlauf #<?= (int) ($candidateRunId ?? 0) ?></strong> · offene Fälle bitte je Feld entscheiden.</p><button type="button" class="btn btn-sm btn-outline-secondary" id="candidate-toggle-all" aria-expanded="false"><i class="fa-solid fa-angles-down me-1" aria-hidden="true"></i>Alle aufklappen</button></div>
            <?php foreach ($candidateGroups as $candidateGroup): ?>
              <?php if (($candidateGroup['state'] ?? '') === 'accepted' || ($candidateGroup['state'] ?? '') === 'resolved') continue; ?>
