              <details class="border rounded p-2 mb-2 <?= $conflictFields !== [] ? 'border-warning' : '' ?>"><summary><span class="badge text-bg-<?= ($candidateGroup['state'] ?? '') === 'number_missing' ? 'warning text-dark' : 'danger' ?> me-1"><?= htmlspecialchars((string) ($candidateGroup['state'] ?? 'offen')) ?></span><?= (int) ($candidateGroup['source_count'] ?? 0) ?> Quellen · <?= htmlspecialchars(substr((string) ($candidateGroup['group_key'] ?? ''), 0, 12)) ?><?php if ($conflictFields !== []): ?> <span class="badge text-bg-warning text-dark ms-1"><i class="fa-solid fa-triangle-exclamation me-1" aria-hidden="true"></i><?= count($conflictFields) ?> Widerspruch<?= count($conflictFields) === 1 ? '' : 'e' ?></span><?php endif; ?></summary>
                <form method="post" class="mt-2"><input type="hidden" name="action" value="import_candidate_decide"><input type="hidden" name="candidate_run_id" value="<?= (int) ($candidateRunId ?? 0) ?>"><input type="hidden" name="group_key" value="<?= htmlspecialchars((string) ($candidateGroup['group_key'] ?? ''), ENT_QUOTES) ?>">
                  <?php if ($conflictFields !== []): ?><div class="alert alert-warning py-2 small"><i class="fa-solid fa-triangle-exclamation me-1" aria-hidden="true"></i><strong>Widersprüchliche Felder:</strong> <?= htmlspecialchars(implode(', ', array_map(static fn(string $field): string => $fieldLabels[$field] ?? $field, $conflictFields))) ?>. Die gelb markierten Tabellenzellen bitte unten entscheiden.</div><?php elseif (($candidateGroup['state'] ?? '') === 'review'): ?><div class="alert alert-warning py-2 small"><i class="fa-solid fa-circle-question me-1" aria-hidden="true"></i>Die Zuordnung ist nicht eindeutig; es gibt aber keinen Feldwert-Widerspruch.</div><?php endif; ?>
                  <div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>Quelle</th><th>Prüfung</th><th>Gerät</th><th>Speicherplatz</th><th>Datum</th><th>Art</th><th>Raum</th><th>Regie</th><th>Ergebnis</th></tr></thead><tbody><?php foreach (($candidateGroup['candidates'] ?? []) as $candidate): $raw = json_decode((string) ($candidate['raw_json'] ?? '{}'), true) ?: []; ?><tr><td><?= htmlspecialchars((string) ($candidate['source_kind'] ?? '')) ?><div class="small text-body-secondary text-break font-monospace"><?= htmlspecialchars((string) ($candidate['source_path'] ?? '')) ?><?= (int) ($candidate['source_row_no'] ?? 0) > 0 ? ':' . (int) $candidate['source_row_no'] : '' ?></div></td><td<?= $cellClass('inspection_number') ?>><?= htmlspecialchars((string) ($candidate['inspection_number'] ?? '—')) ?></td><td<?= $cellClass('device_number') ?>><?= htmlspecialchars((string) ($candidate['device_number'] ?? '—')) ?></td><td<?= $cellClass('storage_slot') ?>><?= htmlspecialchars((string) ($candidate['storage_slot'] ?? '—')) ?></td><td<?= $cellClass('test_date') ?>><?= htmlspecialchars((string) ($candidate['test_date'] ?? '—')) ?></td><td<?= $cellClass('inspection_type') ?>><?= htmlspecialchars((string) ($candidate['inspection_type'] ?? '—')) ?></td><td<?= $cellClass('room_snapshot') ?>><?= htmlspecialchars((string) ($raw['room_snapshot'] ?? $raw['room'] ?? '—')) ?></td><td<?= $cellClass('regie_minutes') ?>><?= htmlspecialchars((string) ($raw['regie_minutes'] ?? '—')) ?></td><td<?= $cellClass('result_status') ?>><?= htmlspecialchars((string) ($raw['result_status'] ?? '—')) ?></td></tr><?php endforeach; ?></tbody></table></div>
                  <?php if (($candidateGroup['state'] ?? '') === 'number_missing'): ?><div class="row g-2 mb-2"><div class="col-md-3"><label class="form-label">Prüfungsnummer</label><input class="form-control form-control-sm" name="field_source[__inspection_number]" required></div><div class="col-md-3"><label class="form-label">Gerätenummer</label><input class="form-control form-control-sm" name="field_source[__device_number]" required></div><div class="col-md-3"><label class="form-label">Prüfdatum</label><input class="form-control form-control-sm" type="date" name="field_source[__test_date]" required></div><div class="col-md-3"><label class="form-label">Prüfart</label><input class="form-control form-control-sm" name="field_source[__inspection_type]" placeholder="SK1" required></div></div><?php endif; ?>
                  <?php if (($candidateGroup['state'] ?? '') === 'number_missing'): ?><details class="mb-2"><summary class="small text-body-secondary"><i class="fa-solid fa-code me-1" aria-hidden="true"></i>Vollständige Quelldaten der Zeile anzeigen</summary><div class="mt-2"><?php foreach (($candidateGroup['candidates'] ?? []) as $candidate): $candidateRaw = json_decode((string) ($candidate['raw_json'] ?? '{}'), true) ?: []; ?><div class="small fw-semibold font-monospace"><?= htmlspecialchars((string) ($candidate['source_path'] ?? '')) ?><?= (int) ($candidate['source_row_no'] ?? 0) > 0 ? ':' . (int) $candidate['source_row_no'] : '' ?></div><pre class="small border rounded bg-body-tertiary p-2 text-break text-wrap"><?= htmlspecialchars((string) json_encode($candidateRaw, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)) ?></pre><?php endforeach; ?></div></details><?php endif; ?>
                  <?php foreach (($candidateGroup['conflicts'] ?? []) as $field => $values): ?><div class="row g-2 mb-2"><label class="col-md-3 col-form-label">Wert für <?= htmlspecialchars((string) $field) ?></label><div class="col-md-9"><select class="form-select form-select-sm" name="field_source[<?= htmlspecialchars((string) $field, ENT_QUOTES) ?>]"><option value="">Bitte auswählen</option><?php foreach (($candidateGroup['candidates'] ?? []) as $candidate): $candidateRaw = json_decode((string) ($candidate['raw_json'] ?? '{}'), true) ?: []; $candidateValue = $candidate[$field] ?? ($candidateRaw[$field] ?? ''); if ((string) $candidateValue === '') continue; ?><option value="<?= (int) ($candidate['id'] ?? 0) ?>"><?= htmlspecialchars((string) ($candidate['source_kind'] ?? '') . ' · ' . (string) $candidateValue) ?></option><?php endforeach; ?></select></div></div><?php endforeach; ?>
                  <div class="d-flex flex-wrap gap-2"><button class="btn btn-primary btn-sm" name="decision" value="merge"><i class="fa-solid fa-code-merge me-1" aria-hidden="true"></i>Feldweise zusammenführen</button><button class="btn btn-secondary btn-sm" name="decision" value="separate">Getrennt importieren</button><button class="btn btn-outline-danger btn-sm" name="decision" value="discard">Verwerfen</button></div>
                </form>
              </details>
            <?php endforeach; ?>
          <?php endif; ?>
        </div>
      </details>
    <?php endif; ?>
